(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sm"] = {"ui":{"skip":"Alu i le anotusi","back":"← Toe foʻi i AI-gile","lang.button":"Gagana: {name}","lang.dialog":"Filifili se gagana","lang.search":"Suʻe gagana","lang.none":"E leai se gagana e tutusa","lang.notYet":"E leʻi faaliliuina le {name}","theme.aria":"Sui mai le autu malamalama i le pogisa","theme.toLight":"Sui i le autu malamalama","theme.toDark":"Sui i le autu pogisa","index.title":"AI-gile: lau ʻau AI faatupu polokalama, i le tasi laupapa","index.description":"O le AI-gile o se laupapa kanban mo ʻau tusi polokalama AI. E latou galulue a e moe oe; e te maua se faaputuga puupuu o mea e te filifili ai, suʻesuʻe ma talia.","hero.logoAlt":"Ata o le laupapa AI-gile","hero.h1.html":"Lau ʻau AI faatupu polokalama, i le tasi&nbsp;laupapa.","hero.alpha":"🐣 Pre-alpha tapunia","hero.alphaTitle":"Muamua ma le i uma: faafetai i lou taumafai!","hero.lede":"E latou fausia a e moe oe. E te ala mai i se faaputuga puupuu: ni fesili e ono, ni mea e ono e suʻesuʻe, ma le tasi pe lua taimane viole. Kiliki, talia, ma toe foʻi i lau kofe.","dl.windows":"Polokalama Windows","dl.browser":"Tatala i lau browser","dl.soon":"E le o toe umi","dl.notify":"🔔 Logo mai ina ua tatala","dl.notifySmall":"Alpha poʻo le beta","hero.secondary":"Agile, ae e le manaʻomia lava e le ʻau le kofe o le fono puupuu. (Ae latou te faia pea fono puupuu.)","pitch.h2":"AI-gile i le tele o upu e te manaʻo ai","pitch.lede":"Filifili se umi, mai le upu e tasi i le 144. O umi taʻitasi o se faamatalaga tuʻufaatasi, na tusia mo lena lapopoa. Toso le faasaga pe faaaoga ki o le keyboard.","pitch.rangeLabel":"Umi i upu","pitch.dice":"🎲 isi lomiga","pitch.words.other":"{n} upu","pitch.letters.other":"{n} mataitusi","pitch.chars.other":"{n} mataitusi","count.line.html.other":"{n} kāte i luga o le laupapa nei","features.aria":"O le a le mea e faia","f.pile.h":"Le tasi faaputuga mo oe","f.pile.html":"O <b>Mo oe</b> e tuufaatasia mea uma o loo faatali ia te oe, i poloketi uma: fesili, mea e suʻesuʻe, galuega e na o le tagata e mafai ona faia. O lau laina e taʻu atu le mea o le a sosoo ai ma le umi.","f.sleep.h":"ʻAu e galulue a e moe oe","f.sleep.p":"O poloketi taʻitasi e iai se taʻitaʻi ma se ʻau o sui AI. Tusi se faamatalaga i luga o se kāte ona ala lea o le ʻau, faia le galuega, ma toe tuuina atu ma laasaga e mafai e se tagata vaivai ona mulimuli ai.","f.tester.h":"E muamua siaki e se AI suʻesuʻe","f.tester.p":"Aʻo leʻi oo atu se mea ia te oe, e mulimuli le suʻesuʻe i laasaga i se kopi o le polokalama ma faaali le mea na ia vaai i ai, faatasi ma se ata o le mataʻitusi. Iloilo mea na pasia ma talia i le tasi kiliki.","f.proof.h":"Faamaoniga, e le o folafolaga","f.proof.p":"O le tuuina atu taʻitasi e faaali ai le mea na suia: faila, eseesega, ata o le mataʻitusi. E te le manaʻomia ona tatalaina polokalama uma e vaai pe ua uma.","f.chat.h":"Talanoa ma ou taʻitaʻi","f.chat.p":"O se laina e pei o Discord: le tasi ata mo poloketi taʻitasi, taimane viole mo mea e manaʻomia ai oe. Auina atu se manatu i se taʻitaʻi; e ia faia ma kāte ma se fuafuaga, faatasi ma se faamau ✅ Alu.","f.tidy.h":"E faʻatulaga e ia lava","f.tidy.p":"O kāte felavasaʻi e tuufaatasia, o ulutala fenumiai e faasaʻoina, ma o se siakiga token e tausia le code e vaivai. E le tele mea e sui ai, e le tele mea e mafaufau ai.","f.private.h":"O oe lava, i lau komepiuta","f.private.li1":"E galue le laupapa i lau lava masini ma e na o oe e tali atu ai.","f.private.li2":"O feʻau tuusao i le va o tagata ua faamaufaailogaina mai le pito i le pito.","f.private.li3":"E leai ni teugatupe, e leai ni nofoaga mulimuli, e leai ni cookies.","f.lang.h":"I lau gagana","f.lang.p":"E sili atu i le 120 gagana, mai le Holani, Uelisi ma Iapani i le pirate, Yoda ma Klingon, faatasi ma se sui vave i le Igilisi mo upu a le ʻau faatupu polokalama.","tl.aria":"Taimi mai le talanoaga muamua i le fuafuaga","tl.h2":"Mai le talanoaga muamua i mea o le a sosoo ai","tl.lede":"Aso ma taimi moni, i lou itu taimi. Ina ua mavae le aso nei o le fuafuaga, e leai ni aso o folafolaina.","tl.today":"Aso nei","tl.planned":"fuafuaina","tl.cards.other":"{n} kāte","join.h2":"Auai mai","join.lede":"O loo fausia AI-gile e se tagata laʻitiiti ma le tele o sui onosaʻi. O le taimi nei e faalilolilo, i se alpha tapunia ma uo. E te manaʻo e taumafai pe a tatala?","join.btn":"Lesisita le fiafia","join.small":"O le a matou tusi atu i le imeli, e leai se isi mea","footer.tag":"AI-gile. E leai ni nofoaga mulimuli, e leai ni cookies, e leai se kofe o le fono puupuu.","footer.licence":"Laisene pisinisi","footer.status":"Tulaga","form.sending":"O auina atu…","form.failed":"E leʻi galue: toe taumafai mulimuli ane.","form.offline":"E leʻi mafai ona oo atu i AI-gile: toe taumafai mulimuli ane.","interest.title":"AI-gile: logo mai ina ua tatala le alpha","interest.description":"Tuu mai lau imeli e iloa ai pe a tatala le alpha poʻo le beta tapunia o AI-gile.","interest.h1":"🔔 Logo mai ina ua tatala","interest.lede":"O AI-gile o loo i le pre-alpha tapunia. Tuu mai lau imeli ona matou tusi atu lea i le tasi taimi, pe a iai se avanoa mo oe.","interest.email":"Lau imeli","interest.which":"O le fea suega?","interest.alpha":"Alpha tapunia: muamua, ma le faigata, e tele suiga","interest.beta":"Beta: sili atu le mausali, mulimuli ane","interest.both":"Se tasi, po o le fea e muamua mai","interest.submit":"Tuu aʻu i le lisi","interest.thanks":"Faafetai! O iai oe i le lisi.","interest.kept":"E teuina na o lau imeli ma le suega na e filifilia, mo lenei lisi lava. E leai se nusipepa, e leai ni nofoaga mulimuli.","licence.title":"AI-gile: laisene pisinisi","licence.description":"E te faaaogaina AI-gile i lau pisinisi? Talosaga mo se laisene pisinisi e leai se totogi.","licence.h1":"📜 Laisene pisinisi","licence.lede":"E te faaaogaina AI-gile i le galuega? Taʻu mai po o ai oe ma le mea e te faia. Afai e aogā, e leai se totogi o le laisene.","licence.company":"Kamupani","licence.website":"Initaneti","licence.what":"O le a le mea e te faia","licence.how":"Le auala e fesoasoani ai i le lalolagi","licence.email":"Imeli","licence.submit":"Talosaga","licence.thanks":"Faafetai! O le a matou toe tali atu i le imeli.","status.title":"Tulaga o AI-gile","status.h1":"Tulaga o AI-gile","status.quiet":"Ua filemu uma","status.checking":"O siaki…","status.offline":"E le mafai ona oo atu i le auaunaga o le tulaga i le taimi nei (o toe taumafai)","status.updated":"faafouina {ago}","status.justNow":"ua na o nei","status.min":"{n} minute ua mavae","status.hours":"{n} itula ua mavae","status.days":"{n} aso ua mavae","pitch.words.one":"{n} upu","pitch.letters.one":"{n} mataitusi","pitch.chars.one":"{n} mataitusi","count.line.html.one":"{n} kāte i luga o le laupapa nei","tl.cards.one":"{n} kāte","live.h2":"Matamata i lona fausiaina, ola","live.caption":"Ua fa'ae'e uma pepa: e te va'ai i foliga o le galuega, e le o ni upu.","live.watching.one":"ola: {n} o matamata","live.watching.other":"ola: {n} o matamata","live.offline":"O lo'o malolo sina le fa'amaumauga ola. Toe afio mai a e le'i umi.","live.cols":"Backlog|E fai|O loʻo faia|O loʻo siaki e le 'au|Mo oe e test|Mo le 'au|Ua uma","live.last.now":"Na sii le kata mulimuli i le taimi nei lava","live.last.min.one":"Na sii le kata mulimuli i le {n} minute ua mavae","live.last.min.other":"Na sii le kata mulimuli i minute e {n} ua mavae","live.last.hour.one":"Na sii le kata mulimuli i le {n} itula ua mavae","live.last.hour.other":"Na sii le kata mulimuli i itula e {n} ua mavae","live.last.day.one":"Na sii le kata mulimuli i le {n} aso ua mavae","live.last.day.other":"Na sii le kata mulimuli i aso e {n} ua mavae"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Tuuina."]},{"n":2,"texts":["Kanban robots.","Sui, faatulagaina.","Manatu, fausia."]},{"n":3,"texts":["Kanban mo robots.","Manatu e avea gaoioiga.","Kanban sui, leai totogi."]},{"n":5,"texts":["Laupapa kanban e taitaia e sui.","Tusi kāte. E fausia e sui.","Leai totogi, i totonu, suʻesuʻeina, malie."]},{"n":8,"texts":["Laupapa kanban leai totogi e galue ai sui AI.","Tusi se manatu. E fausia e sui. E te talia.","Agile mo se tagata ma robots onosaʻi e tele."]},{"n":13,"texts":["Laupapa kanban i lau komepiuta, e piki kāte ai sui AI e galue.","Tusi se manatu. E fausia e sui. Suʻesuʻe e siaki. Oe e talia.","Leai totogi, leai teugatupe, leai nofoaga mulimuli: se laupapa, ni robots, ma oe e pule."]},{"n":21,"texts":["O le AI-gile o se laupapa kanban mo galulue ma sui AI e tusi polokalama. E latou piki kāte; e te suʻesuʻe ma talia.","Poloketi taʻitasi e iai se taʻitaʻi ma ʻau sui AI. Tusi se faamatalaga i se kāte, ona amata lea o le galuega.","Laupapa galuega totino e leai se totogi, i lau lava komepiuta. E robots le ʻau. O oe e fai atu ioe."]},{"n":34,"texts":["Tuu manatu i luga o le laupapa. E liliu e se ʻau sui AI i gaoioiga e galue, suʻesuʻe, ma toe tuuina atu ma laasaga. E leai se mea ua uma seʻia e fai mai oe.","O le AI-gile o se laupapa kanban na fausia e Rich faatasi ma sui AI o loo ia pulea nei. E leai se totogi, e galue i lau komepiuta, ma faasoa i uo, e le faatauina.","Mafaufau i se laupapa kanban masani, ma koluma mai le Backlog i le Ua uma, ae o kāte e piki e sui AI. Latou lipotia le alualu i luma, fesili pe a tu, ma faatali pea i lau faatagaga."]},{"n":55,"texts":["O le AI-gile o se laupapa kanban e fausia le ʻau i sui AI. O poloketi taʻitasi e iai se taʻitaʻi e fuafuaina le galuega ma fesoasoani e faia. A uma se gaoioiga, e suʻesuʻe e se AI suʻesuʻe ma ave ai se ata o le mataʻitusi, ona alu lea i lau faaputuga. Talia, pe tusi se faamatalaga ona toe faia lea e latou.","Na amata o se auala e mulimuli ai le tagata e tasi i le tele o fonotaga tusi polokalama AI, ona tupu lea i se laupapa moni. E galue i lau masini, e leai se teugatupe, e leai ni nofoaga mulimuli. E leai se totogi mo uo. E le i uma, ia faatalitali i ni pito faigata.","O le faamatalaga faamaoni lea. E tatau pea ona e maua manatu, ma e tatau pea ona e siaki taunuuga. O le AI-gile e faia mea uma i le va: e tausia kāte i le faasologa, ala le sui saʻo pe a e tusi se faamatalaga, faaali saʻo le mea na suia, ma tuu mea uma i se faaputuga puupuu mo oe."]},{"n":89,"texts":["O le AI-gile o se laupapa kanban e leai se totogi i lau komepiuta. I poloketi taʻitasi e iai se ʻau sui AI: se taʻitaʻi e liliu au manatu i kāte ma se fuafuaga, ma fesoasoani e piki kāte. A fausia se mea, e mulimuli se AI suʻesuʻe i laasaga ma faaali le mea na ia vaai i ai. Ona faatali lea i se faaputuga e igoa Mo oe. E te talia, pe tusi se faamatalaga ona toe taumafai lea. E leai se mea e oo i le Ua uma e aunoa ma oe.","Nisi mea e te le faatalitalia. O se leoleo po e faatumu le koluma E fai a e moe oe, ma filifili kāte e le manaʻomia ai se tali. O se tagaga token e faaali le aofaʻi e faaaoga e sui, ma o le Auala e leai ni token e taofi ai. E mafai ona e feʻau atu i uo, faamaufaailogaina mai le pito i le pito. E tautala le laupapa i le tusa ma le 120 gagana, e aofia ai Holani, pirate ma Klingon. E leai se totogi, ma e leai se tasi o taumafai e faatau atu.","O le AI-gile o se poloketi laʻitiiti totino, e le o se kamupani. Na manaʻo Rich e tausia ni poloketi tusi polokalama AI e aunoa ma le tatalaina o polokalama uma, o lea na ia fausia ai se laupapa faatasi ma sui, ona faaaoga lea e fausia le vaega o totoe. O loo i le pre-alpha tapunia: e galue, e tele lava, mo ni uo e toʻaitiiti. E leai se itulau o tau, e leai se nusipepa. Afai e aogā, talosaga e taumafai pe a sili atu le tatala."]},{"n":144,"texts":["O le AI-gile o se laupapa kanban mo le tagata e tasi ma le tele o sui AI. E galue i lau lava komepiuta ma e leai lava se totogi. E te faaopoopo poloketi, ma taʻitasi e maua se taʻitaʻi ma se ʻau laʻitiiti. E te talanoa ma le taʻitaʻi, e pei o Discord, ma faamatala se manatu; e liliu e le taʻitaʻi i kāte ma se fuafuaga, ona faatali lea seʻia e kiliki Alu. E faia e le ʻau kāte e tusa ai ma le faamuamua, e faaaoga se laina poloaiga faigofie na faia mo faiga gagana. Aʻo leʻi toe foʻi se mea ia te oe, e mulimuli se AI suʻesuʻe i laasaga i se kopi o le polokalama ma faapipiʻi se ata o le mataʻitusi. O galuega ua uma e oo i lau faaputuga faatasi ma faila ua suia ma eseesega. E te talia, pe tuu se faamatalaga ona ala lea o le ʻau ma toe taumafai. Na o oe e mafai ona e suia se kāte i le Ua uma.","O se aso ma AI-gile, tusa lava. I le afiafi e te tuu ni faamatalaga: o lenei faamau o loo i se mea sese, o lena lisi e tatau ona faatulagaina, e mafai ona tatou maua se auala pogisa. E te alu e moe. E faitau e sui faamatalaga, faia suiga, suʻesuʻe ma toe tuuina atu ia te oe. Afai e mutu le koluma E fai, e faatumuina e le leoleo po mai le backlog i kāte e le manaʻomia ai se tali mai ia te oe. I le taeao o loo iai se faaputuga puupuu: ni fesili e ono ma ni mea e suʻesuʻe, taʻitasi ma laasaga e mafai e se tagata moeiini ona mulimuli ai ma se ata o loo galue. E te alu i totonu, talia mea lelei ma toe auina atu isi. Ona e taumafa lea o le taeao, lea e le mafai pea e sui ona fesoasoani i ai.","Muamua, le mea e le o le AI-gile. E le o se startup, e le o faatauina, ma e leai se tasi o aoina au faamatalaga. O se laupapa e leai se totogi e galue i lau komepiuta, e leai ni teugatupe, e leai ni nofoaga mulimuli ma e leai ni cookies. O le mea e iai: o se nofoaga e tasi mama e vaai ai i poloketi tusi polokalama AI uma i le taimi e tasi, ma se ʻau o sui e faia kāte ma oe e faia filifiliga. E tuufaatasia kāte felavasaʻi, faasaʻo ulutala fenumiai, ma mataʻituina ia tumau le code vaivai. E tautala i le tusa ma le 120 gagana, mai le Holani ma le Flemish i le pirate ma le Klingon. O loo i le pre-alpha tapunia, o lea e faigata i nisi pito. Afai e foliga manaia, talosaga ma le agalelei ona e maua lea ma le vave."]}],"quips":{"1":"Le upu e tasi. Natia. Masalo e sili.","3":"Upu e tolu. E sili atu le faamaoni nai lo le tele o itulau o oloa.","8":"Upu e valu. E puupuu pea nai lo se fono puupuu.","21":"O umi o story points, i le ala. Ioe, e faapea lava.","55":"Upu e lima sefulu ma le lima. E lua kāte na uma aʻo e faitau.","144":"O le mea umi lea. E leai se 233. Ua alu e moe sui."}},"timeline":{"first-idea.name":"Le manatu muamua","first-idea.line":"O le talanoaga sili ona muamua, aʻo leʻi iai se code.","first-board.name":"Le laupapa muamua","first-board.line":"O se laupapa e mulimuli i lona lava fausiaga: kāte, koluma, toso ma tuu, poloketi.","team-roles.name":"ʻAu ma tofiga","team-roles.line":"Faamatalaga o sui, faʻataʻitaʻiga o ʻau, avanoa ma o ai e faia le a.","install.name":"Faapipiʻiga ma lomiga","install.line":"O se zip e mafai e se uo ona faapipii, faafouga otometi, auala ma toe foʻi.","usage-saver.name":"Faasaoina o le faaaogaina","usage-saver.line":"Fuaina le tau o le faatinoga, tausia le code e vaivai, faasaoina lau tapulaa.","friends.name":"Uo ma le faasoaina","friends.line":"Feʻau tuusao, se relay faalilolilo, valaaulia, tofiga ma poloketi faasoa.","languages.name":"Gagana","languages.line":"O tusitusiga uma o le mataʻitusi i se faila gagana, ma le Holani ma le Flemish muamua.","ai-tester.name":"AI suʻesuʻe","ai-tester.line":"E muamua siaki e se suʻesuʻe tuuina atu uma ma faaali le mea na ia vaai i ai.","website.name":"Le initaneti","website.line":"aigile.lol, le teaser ma lenei taimi.","streaming.name":"Talanoaga ma faasalalauga","streaming.line":"Discord, Twitch, OBS, auala faasalalau, GIF ma emoji.","no-ai.name":"Lomiga e leai se AI","no-ai.line":"O se laupapa mo tagata e tusi polokalama e aunoa ma AI, ma laupapa lautele.","night-watch.name":"Leoleo po","night-watch.line":"O se leoleo ma se Scrum Master e tausia ʻau i galuega a e moe oe.","p-more.name":"Isi mea uma","p-more.line":"Manatu laiti o loo faatali pea i le latou taimi.","p-android.name":"Telefoni ma Android","p-android.line":"Oo atu i lau laupapa mai se telefoni, ona sosoo ai lea ma se polokalama Android.","p-release.name":"Alpha ma mulimuli ane","p-release.line":"Alpha tapunia, le initaneti ola, ona sosoo ai lea ma le beta.","p-languages.name":"Sili atu gagana","p-languages.line":"Sili atu i le selau gagana, ma se auala tofo mo tagata aʻoaʻo.","p-engines.name":"Sili atu afi AI","p-engines.line":"Filifili Claude, Codex poʻo Gemini mo sui taʻitasi.","p-pro.name":"Faiga faapolofesa","p-pro.line":"Faailoga o lamatiaga, faitotoʻa tuufaatasia, kāte o mea e tutupu ma puipuiga.","p-self.name":"Tausia oe","p-self.line":"Auala o le vaivai, faamanatu o le tausiga o oe lava ma le 4:20.","p-servers.name":"Server ma le tuputupu aʻe","p-servers.line":"Setiina lautele o server, tofiga ma fuafuaga mo le tuputupu aʻe.","p-livestream.name":"Faaopoopoga faasalalau","p-livestream.line":"Talanoaga Twitch, emoji faapitoa ma se vaaiga ola lautele."},"words":{"button":"📖 Upu fa'ata'ita'i","h":"📖 Faʻamatalaga o upu fa'ata'ita'i","intro":"O upu e faʻaoga e le au fa'ata'ita'i (ma 'au AI), i upu faigofie.","search":"Su'e se upu…","none":"E leai se upu e fetaui.","close":"Tapuni","list":[{"id":"backlog","word":"Backlog","text":"Manatu ma galuega e leʻi fuafuaina. E leai se mea iina e galueina seʻia siitia i le E fai."},{"id":"sprint","word":"Sprint","text":"O se vaitaimi puʻupuʻu o galuega (e masani ose vaiaso po o le lua) ma se aofa'iga o kāte ua maliega e faamaeaina.","also":["sprints"]},{"id":"standup","word":"Fonotaga puʻupuʻu","text":"O se siakiga vave: o le a le mea na faia e sui taʻitasi o le 'au, o le a le mea latou te faia a sosoo, ma le mea o taofia ai i latou.","also":["standup","stand-ups","stand-up"]},{"id":"bug","word":"Bug","text":"O se mea e le galue e pei ona tatau.","also":["bugs"]},{"id":"test","word":"Test","text":"O le taumafai i se galuega ua uma e siaki pe faia le mea na ole atu ai, a o leʻi taliaina.","also":["tests"],"noTip":1},{"id":"commit","word":"Commit","text":"O se ata ua teuina o le code, faatasi ai ma se faʻamatalaga puʻupuʻu o le mea na suia. E mafai ona e toe foʻi i se tasi i so'o se taimi.","also":["commits"]},{"id":"push","word":"Push","text":"O le auina atu o ata ua teuina (commits) mai lenei komipiuta i le GitHub, ina ia teuina ma faasoa."},{"id":"branch","word":"Branch","text":"O se laina e ese o galuega i le code, ina ia mafai ona faia suiga e aunoa ma le paʻi i le fofoga autu.","also":["branches"]},{"id":"merge","word":"Merge","text":"O le toe tuufaatasia o suiga a se branch i le fofoga autu."},{"id":"repo","word":"Repo","text":"O le faila o le poloketi o le code ma lona tala atoa o commits, e masani ona teuina foi i le GitHub.","also":["repository"]},{"id":"refactor","word":"Refactor","text":"O le faʻamama o le code e aunoa ma le suia o mea e faia: faila laiti, igoa manino, e le toe faia."},{"id":"deploy","word":"Deploy","text":"O le tuuina atu o se fofoga fou ia ola, e pei o se sava e faʻaoga ai e tagata."},{"id":"kanban","word":"Kanban","text":"O se laupapa e iai koluma (E fai, O faia, Ua uma) e siitia ai kāte mai le agavale i le taumatau a o faia galuega."},{"id":"wip","word":"Tapulaʻa WIP","text":"Galuega o faagaoioi: le tele aupito o kāte e tatau ona taofi e se koluma, ina ia faamaea e le 'au mea a o leʻi amata nisi.","also":["WIP","WIP limit"]},{"id":"pr","word":"Pull request","text":"O le ole atu e siaki ma tuufaatasia suiga a se branch i le fofoga autu.","also":["PR"]},{"id":"hook","word":"Hook","text":"O se poloaiga laiti e faagaoioi e ia lava i se taimi ua seti, e.g. pe a amata se sesisi AI, ina ia faʻalogo le 'au i au faʻamatalaga.","also":["hooks"]},{"id":"token","word":"Token","text":"O le iunite e faitauina ai le faʻaaogaina o le AI: pe tusa ma ni nai mataitusi o tusitusiga ua faitau po o tusia. E itiiti token, e tele totoe o lau fuafuaga.","also":["tokens"]},{"id":"agent","word":"Sooupu","text":"O se AI e galue na o ia i se galuega: faitau le code, faia suiga, faagaoioi siakiga, ma lipotia mai.","also":["agent","agents","sooupu"]}]}};
